CREATE TABLE IF NOT EXISTS public."promotional_video_comments" (
    "comment_id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "user_id" integer NOT NULL REFERENCES public."users" ("user_id") ON DELETE CASCADE,
    "comment" text NOT NULL CHECK (length(btrim("comment")) BETWEEN 1 AND 1000),
    "created_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS "promotional_video_comments_created_at_idx"
    ON public."promotional_video_comments" ("created_at" DESC);

CREATE TABLE IF NOT EXISTS public."promotional_video_likes" (
    "user_id" integer PRIMARY KEY REFERENCES public."users" ("user_id") ON DELETE CASCADE,
    "created_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP
);

ALTER TABLE public."promotional_video_comments" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."promotional_video_likes" ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public."promotional_video_comments", public."promotional_video_likes"
    FROM PUBLIC, anon, authenticated;
GRANT ALL ON TABLE public."promotional_video_comments", public."promotional_video_likes"
    TO service_role;
GRANT USAGE, SELECT ON SEQUENCE public."promotional_video_comments_comment_id_seq"
    TO service_role;

CREATE OR REPLACE FUNCTION public.get_promotional_video_discussion()
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $function$
    SELECT jsonb_build_object(
        'likes_count', (
            SELECT count(*) FROM public."promotional_video_likes"
        ),
        'liked_by_me', CASE
            WHEN auth.uid() IS NULL THEN false
            ELSE EXISTS (
                SELECT 1
                  FROM public."promotional_video_likes" AS video_like
                  JOIN public."users" AS account ON account."user_id" = video_like."user_id"
                 WHERE account."auth_user_id" = auth.uid()
                   AND account."is_active" = 1
            )
        END,
        'comments', COALESCE((
            SELECT jsonb_agg(recent_comment."comment_data"
                ORDER BY recent_comment."created_at" DESC, recent_comment."comment_id" DESC
            )
              FROM (
                SELECT
                    jsonb_build_object(
                    'comment_id', video_comment."comment_id",
                    'full_name', COALESCE(NULLIF(btrim(account."full_name"), ''), account."username", 'User'),
                    'comment', video_comment."comment",
                    'created_at', video_comment."created_at"
                    ) AS "comment_data",
                    video_comment."created_at",
                    video_comment."comment_id"
                  FROM public."promotional_video_comments" AS video_comment
                  JOIN public."users" AS account ON account."user_id" = video_comment."user_id"
                 ORDER BY video_comment."created_at" DESC, video_comment."comment_id" DESC
                 LIMIT 100
              ) AS recent_comment
        ), '[]'::jsonb)
    );
$function$;

CREATE OR REPLACE FUNCTION public.add_promotional_video_comment(p_comment text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE
    app_user_id integer;
    new_comment_id bigint;
    comment_value text := btrim(COALESCE(p_comment, ''));
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Sign in to post a comment';
    END IF;
    IF length(comment_value) NOT BETWEEN 1 AND 1000 THEN
        RAISE EXCEPTION 'Comments must be between 1 and 1,000 characters';
    END IF;

    SELECT account."user_id"
      INTO app_user_id
      FROM public."users" AS account
     WHERE account."auth_user_id" = auth.uid()
       AND account."is_active" = 1;
    IF app_user_id IS NULL THEN
        RAISE EXCEPTION 'An active account is required to post a comment';
    END IF;

    INSERT INTO public."promotional_video_comments" ("user_id", "comment")
    VALUES (app_user_id, comment_value)
    RETURNING "comment_id" INTO new_comment_id;

    RETURN jsonb_build_object('type', 'success', 'comment_id', new_comment_id);
END;
$function$;

CREATE OR REPLACE FUNCTION public.toggle_promotional_video_like()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE
    app_user_id integer;
    changed_rows integer;
    is_liked boolean;
    total_likes bigint;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Sign in to like the video';
    END IF;

    SELECT account."user_id"
      INTO app_user_id
      FROM public."users" AS account
     WHERE account."auth_user_id" = auth.uid()
       AND account."is_active" = 1;
    IF app_user_id IS NULL THEN
        RAISE EXCEPTION 'An active account is required to like the video';
    END IF;

    INSERT INTO public."promotional_video_likes" ("user_id")
    VALUES (app_user_id)
    ON CONFLICT ("user_id") DO NOTHING;
    GET DIAGNOSTICS changed_rows = ROW_COUNT;

    IF changed_rows = 0 THEN
        DELETE FROM public."promotional_video_likes"
         WHERE "user_id" = app_user_id;
        is_liked := false;
    ELSE
        is_liked := true;
    END IF;

    SELECT count(*) INTO total_likes FROM public."promotional_video_likes";
    RETURN jsonb_build_object(
        'type', 'success',
        'liked', is_liked,
        'likes_count', total_likes
    );
END;
$function$;

REVOKE ALL ON FUNCTION public.get_promotional_video_discussion()
    FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.add_promotional_video_comment(text)
    FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.toggle_promotional_video_like()
    FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.get_promotional_video_discussion()
    TO anon, authenticated;
GRANT EXECUTE ON FUNCTION public.add_promotional_video_comment(text)
    TO authenticated;
GRANT EXECUTE ON FUNCTION public.toggle_promotional_video_like()
    TO authenticated;
